def fail_duplicate_pending_reports(apps, schema_editor):
    """Keep the newest pending report per identical request; older duplicates are marked failed."""
    Report = apps.get_model("automation", "WorkspaceReport")
    seen = set()
    for report in Report.objects.filter(state="pending").order_by("-created_at", "-id"):
        key = (report.workspace_id, report.report_type, report.project_id, report.sprint_id)
        if key in seen:
            report.state, report.error = "failed", "Superseded by an identical request."
            report.save(update_fields=["state", "error"])
        seen.add(key)


